        end
    end
    
    --local goCount = self.LayoutBtn1.transform.childCount - 1 --减去默认prefab的数量
    --if goCount > #currentData then
    --    for i = #currentData + 1, goCount do --复用时隐藏多出来的
    --        KTool.SetActive(self.btnNodeMap1[i], false)
    --    end
    --end
    for i = 1, table.count(currentData) do
        local go
        local k = i
        local v = currentData[checkString(k)]
        go = self.btnNodeMap1[k]
        if not go then
            local btn = self.LayoutBtn1.transform:Find("Icon"..v.type)
            go = CfUtils.InstantiateGo(btn, self.LayoutBtn1.gameObject)
            go.name = "btnNode"..k
            self.btnNodeMap1[k] = go.gameObject
        end
        local goEnv = CfUtils.GetLuaScr(go, "Game.UI.Patrol.PatrolChoosePanelEventCell")
        local typeData = CfUtils.GetCfVo(AutoIds.IdSetting351, "PatrolPointTypeVo",v.type)

        local btnData = {
            iconPath = typeData.icon,
            text = typeData.name,
            index = checkNumber(k),
        }
        goEnv:FreshBaseUI(btnData)
        goEnv:SetBtnCallBack(function ()
            --cs_coroutine.start(function()
                --UIRaycastBlocker:AddCondition("PatrolMainChooseNode")
                --cs_coroutine.yield_return(chooseAnimTime)
                MazeMgr:BtnActionShowEventPanel(k)
                --UIRaycastBlocker:RemoveCondition("PatrolMainChooseNode")
            --end)
        end)
        KTool.SetActive(go, true)
    end
end

---@param index number 当前选中的index
function PatrolChoosePanel:FreshNext(index)
    if isNull(index) and MazeMgr.currentPos ~= 0 then
        index = MazeMgr.currentPos
    end
    local nextData = MazeMgr.nextInfo
    local hasNext = table.count(nextData) > 0
    KTool.SetActive(self.LayoutBtn2.transform.parent, hasNext)
    KTool.SetActive(self.Arrow1.transform.parent, hasNext)
    if hasNext then
        self.TxtNumber2.text = checkNumber(MazeMgr.currentFloor) + 1
        local goCount = self.LayoutBtn2.transform.childCount - 1 --减去默认prefab的数量
        if goCount > #nextData then
            for i = #nextData + 1, goCount do --复用时隐藏多出来的
                KTool.SetActive(self.btnNodeMap2[i], false)
            end
        end
        for i = 1, table.count(nextData) do
            local go
            local k = i
            local v = nextData[checkString(k)]
            go = self.btnNodeMap2[k]
            if not go then
                go = CfUtils.InstantiateGo(self.Btn2, self.LayoutBtn2.gameObject)
                go.name = "btnNode"..k
                self.btnNodeMap2[k] = go.gameObject
            end
            local goEnv = CfUtils.GetLuaScr(go, "Game.UI.Patrol.PatrolChoosePanelEventCellNext")
            local typeData = CfUtils.GetCfVo(AutoIds.IdSetting351, "PatrolPointTypeVo",v.type)
            local btnData = {
                iconPath = typeData.icon,
                text = typeData.name,
                --index = checkNumber(k),
                isNextIcon = self:IsNextIcon(k, index)
            }
            goEnv:FreshBaseUI(btnData)
            KTool.SetActive(go, true)
        end
    end
end

function PatrolChoosePanel:PlayChooseAnim(index)
    local isChoose = not isNull(index)
    KTool.SetActive(self.ImgBigArrow, not isChoose)
    KTool.SetActive(self.WarningGroup, not isChoose)
    if not isChoose then
        --CfUtils.PlayAnimator(self.Root, "Back")
    else
        --CfUtils.PlayAnimator(self.Root, "Choose")

        --箭头
        if self.selectArrow then --之前选中的
            KTool.SetActive(self.selectArrow, false)
        end
        local currentData = MazeMgr.currentInfo
        local nextData = MazeMgr.nextInfo
        if table.count(nextData) == 1 then
            if index == (table.count(currentData) + 1)/2 then
                self.selectArrow = self.Arrow1
            elseif index == (table.count(currentData) + 1)/2 - 1 then
                self.selectArrow = self.Arrow6
            elseif index == (table.count(currentData) + 1)/2 + 1 then
                self.selectArrow = self.Arrow5
            end
        else
            if table.count(currentData) == 1 then
                self.selectArrow = self.Arrow2
            elseif index == 1 then
                self.selectArrow = self.Arrow3
            elseif index == 2 then
                self.selectArrow = self.Arrow2
            elseif index == 3 then
                self.selectArrow = self.Arrow4
            end
        end

        self:FreshNext(index)
    end
    if self.selectArrow then --之前选中的
        KTool.SetActive(self.selectArrow, isChoose)
    end
end

function PatrolChoosePanel:IsNextIcon(k, key)--这边的规则与后端保持一致
    if isNull(key) then
        return true
    end
    k = checkNumber(k)
    key = checkNumber(key)
    local nextData = MazeMgr.nextInfo
    --if table.count(currentData) == 1 then
    --    key = key + 1
    --end
        --local currentPos = checkNumber(MazeMgr.currentPos)
    if (k >= key and k <= key + 2) or table.count(nextData) == 1 then
        return true
    else
        return false
    end
end

function PatrolChoosePanel:OnDestroy()
    Events.RemoveListener(Constants.EventNames.PatrolEventChoose, self.EventEnterChoose)

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return PatrolChoosePanel